.libPaths(c('.R-library',.libPaths()))
suppressPackageStartupMessages({library(sf);library(ggplot2);library(patchwork)})
root<-'output/components/pedestrian-gaps';source('R/pedestrian_gaps.R')
r<-readRDS(file.path(root,'analysis.rds'));h<-r$hex;w<-r$neighborhood
pop<-as.data.frame(targets::tar_read(dam_inputs)$population)
w<-merge(w,pop[,c('h3_id','total_population','children_under_18')],by='h3_id',sort=FALSE)
weighted_q<-function(x,wt,p){use<-is.finite(x)&is.finite(wt)&wt>0;o<-order(x[use]);x<-x[use][o];wt<-wt[use][o];if(!length(x))return(rep(NA_real_,length(p)));sapply(p,function(p)x[which(cumsum(wt)/sum(wt)>=p)[1]])}
summary<-do.call(rbind,lapply(c('hex','neighborhood'),function(k){d<-r[[k]];good<-is.finite(d$gap_score);q<-quantile(d$gap_score[good],c(0,.1,.25,.5,.75,.9,1));data.frame(geography=k,available=sum(good),no_network=sum(d$status=='no_classified_network'),unknown=sum(d$status=='unclassified_inventory'),partial_boundary=sum(d$boundary_partial),minimum=q[1],p10=q[2],p25=q[3],median=q[4],p75=q[5],p90=q[6],maximum=q[7])}))
write.csv(summary,file.path(root,'summary.csv'),row.names=FALSE)
coverage<-do.call(rbind,lapply(c('hex','neighborhood'),function(k)do.call(rbind,lapply(c('total_population','children_under_18'),function(g){d<-r[[k]];wt<-pop[[g]][match(d$h3_id,pop$h3_id)];known<-is.finite(wt);ok<-is.finite(d$gap_score);data.frame(geography=k,group=g,known_population=sum(wt[known]),represented=sum(wt[known&ok]),represented_percent=100*sum(wt[known&ok])/sum(wt[known]),unknown_weight_hexes=sum(!known),weighted_median=weighted_q(d$gap_score,wt,.5))}))))
write.csv(coverage,file.path(root,'population_coverage.csv'),row.names=FALSE)
comparison<-merge(h[,c('h3_id','gap_score')],w[,c('h3_id','gap_score','potential_included_score')],by='h3_id',suffixes=c('_hex','_neighborhood'))
comparisons<-data.frame(comparison=c('Hex versus one-mile neighborhood','Main versus including potential sidewalks'),spearman=c(cor(comparison$gap_score_hex,comparison$gap_score_neighborhood,method='spearman',use='complete.obs'),cor(w$gap_score,w$potential_included_score,method='spearman',use='complete.obs')),median_absolute_change=c(median(abs(comparison$gap_score_hex-comparison$gap_score_neighborhood),na.rm=TRUE),median(abs(w$gap_score-w$potential_included_score),na.rm=TRUE)),max_absolute_change=c(max(abs(comparison$gap_score_hex-comparison$gap_score_neighborhood),na.rm=TRUE),max(abs(w$gap_score-w$potential_included_score),na.rm=TRUE)))
write.csv(comparisons,file.path(root,'sensitivity.csv'),row.names=FALSE)
date_review<-do.call(rbind,lapply(c('hex','neighborhood'),function(k){d<-r[[k]];data.frame(geography=k,flagged=sum(d$completion_date_review),max_score_change=max(d$gap_score-d$dated_as_completed_score,na.rm=TRUE))}))
write.csv(date_review,file.path(root,'completion_date_sensitivity.csv'),row.names=FALSE)
# Matching-window crash history is diagnostic; no crash transformation or composite is adopted.
crashes<-st_transform(targets::tar_read(crash_points),st_crs(r$windows));hits<-st_intersects(r$windows,crashes)
count<-vapply(hits,function(i)length(unique(crashes$crash_id[i])),integer(1))
density<-count/5/(as.numeric(st_area(r$windows))/2589988.110336)
w$annual_ksi_density<-density[match(w$h3_id,r$windows$h3_id)]
write.csv(w,file.path(root,'neighborhood_review.csv'),row.names=FALSE,na='')
geom<-merge(r$hex_geometry,h,by='h3_id');geow<-merge(r$hex_geometry,w,by='h3_id')
map<-function(x,title)ggplot(x)+geom_sf(aes(fill=gap_score),color=NA)+scale_fill_viridis_c(option='magma',direction=-1,limits=c(0,100),na.value='#b8bfc2',name='Gap score')+labs(title=title,subtitle='Missing planned length / completed + planned length')+theme_void(base_size=12)+theme(plot.title=element_text(face='bold'),plot.margin=margin(12,12,12,12))
p<-map(geom,'Within each hex: City portion')+map(geow,'Within one mile of each hex center')+plot_annotation(title='Pedestrian-network gaps | City inventory, November 9, 2026',caption='Higher = more missing network. Gray = unavailable. Maps show origin-assigned values, not the exact location of missing facilities.\nCity portions only; inventory completeness is not independently certified. Crossing quality and ADA condition are not measured.')
ggsave(file.path(root,'gap_maps.png'),p,width=12,height=8,dpi=160);ggsave(file.path(root,'gap_maps.pdf'),p,width=12,height=8)
p1<-ggplot(comparison,aes(gap_score_hex,gap_score_neighborhood))+geom_abline(slope=1,intercept=0,color='grey60')+geom_point(na.rm=TRUE,alpha=.5,size=1.2,color='#286b85')+coord_equal(xlim=c(0,100),ylim=c(0,100))+labs(title='Geography sensitivity',x='Gap score within hex',y='Gap score within one-mile neighborhood')+theme_minimal()
p2<-ggplot(w,aes(gap_score,potential_included_score))+geom_abline(slope=1,intercept=0,color='grey60')+geom_point(na.rm=TRUE,alpha=.5,size=1.2,color='#a14c36')+coord_equal(xlim=c(0,100),ylim=c(0,100))+labs(title='Denominator sensitivity',x='Main gap score',y='Score including potential sidewalks as missing')+theme_minimal()
ggsave(file.path(root,'sensitivity.png'),p1+p2,width=11,height=5,dpi=160)
p3<-ggplot(w,aes(gap_score,annual_ksi_density))+geom_point(na.rm=TRUE,alpha=.5,color='#306778')+labs(title='Pedestrian gaps and serious-crash density',subtitle='Same one-mile, City-clipped neighborhoods; 2020–2024 crashes',x='Pedestrian gap score',y='Annual KSI crashes per square mile')+theme_minimal()
ggsave(file.path(root,'crash_comparison.png'),p3,width=7,height=5,dpi=160)
esc<-function(x){x<-gsub('&','&amp;',as.character(x),fixed=TRUE);x<-gsub('<','&lt;',x,fixed=TRUE);gsub('>','&gt;',x,fixed=TRUE)}
tab<-function(d){d[]<-lapply(d,function(x)if(is.numeric(x))round(x,2)else x);paste0('<table><thead><tr>',paste0('<th>',esc(names(d)),'</th>',collapse=''),'</tr></thead><tbody>',paste(apply(d,1,function(row)paste0('<tr>',paste0('<td>',esc(row),'</td>',collapse=''),'</tr>')),collapse=''),'</tbody></table>')}
cat<-r$network$category_audit;cat$unique_miles<-cat$unique_m/1609.344
html<-paste0('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pedestrian gap measure review</title><style>body{font:17px/1.5 system-ui;max-width:1120px;margin:40px auto;padding:0 24px;color:#18343e}h1,h2{line-height:1.2}img{max-width:100%;height:auto}table{border-collapse:collapse;font-size:13px;display:block;overflow:auto}td,th{padding:8px;border-bottom:1px solid #ccd6da;text-align:left}.note{background:#edf3f5;padding:18px;border-left:4px solid #39728a}a{color:#176484}</style><h1>Pedestrian-network gap measure</h1><p>City inventory snapshot · November 9, 2026 · 1,029 current hex origins</p><div class="note"><b>Gap score = 100 × planned length / (completed + planned length).</b> Completed includes existing sidewalks, driveway crossings, shared-use/protected paths and completed shared streets. Planned sidewalks and planned shared streets count as gaps. Potential sidewalks enter a separate sensitivity. Source categories, not a new requirement on both sides of every road, define the main denominator.</div><h2>Spatial comparison</h2><img src="gap_maps.png" alt="Maps comparing hex and neighborhood pedestrian gap scores"><h2>Distribution</h2>',tab(summary),'<h2>Population coverage</h2><p>Whole-hex population estimates describe residents assigned a neighborhood result, not people actually served by a sidewalk. Unknown population is excluded from weighted summaries.</p>',tab(coverage),'<h2>Facility audit</h2>',tab(cat),'<p>Same-status overlapping lines are dissolved. Conflicting completed/planned linework and unknown types are retained as unknown; affected estimates are unavailable with lower/upper bounds supplied. A point crossing is not overlapping length. One empty source geometry cannot be located and is documented in metadata. Planned segments with a past completion date are flagged; a sensitivity treats that length as completed without overriding the main facility-type classification.</p><h2>Inventory examples</h2><img src="inventory_examples.png" alt="Facility categories on four example streets"><h2>Sensitivity</h2>',tab(comparisons),'<p>Completion-date sensitivity:</p>',tab(date_review),'<img src="sensitivity.png" alt="Sensitivity to geography and inclusion of potential sidewalks"><h2>Relationship to crash density</h2><img src="crash_comparison.png" alt="Crash density versus gap score"><p>The agreed 50/50 combination is recorded, but a combined score awaits the crash-score transformation. No high-burden cutoff is adopted here.</p><h2>Interpretation and limitations</h2><p>This is an inventory completion measure, not a certification of safe routes or ADA compliance. A short missing link can disconnect a route while changing little total length. Both geographies are clipped to the pinned City full- and limited-purpose limits; boundary shares and network lengths are included. An empty denominator is unavailable. Positive inventory length does not certify complete mapping of every street.</p><p>Shared-street lines retain the inventory geometry and are not doubled. Potential-sidewalk inclusion is a broader inventoried-network sensitivity, not a verified reconstruction of sidewalks on both sides of every road.</p><p><a href="hex.csv">Hex results</a> · <a href="neighborhood.csv">One-mile results</a> · <a href="pedestrian_gaps.gpkg">GIS layers</a> · <a href="metadata.json">Source and methods</a></p></html>')
writeLines(html,file.path(root,'review.html'))
print(summary);print(coverage);print(comparisons);print(cat[,c('category','features','unique_miles','overlapping_m_removed')]);cat('\nCrash/gap Spearman: ',cor(w$gap_score,w$annual_ksi_density,method='spearman',use='complete.obs'),'\n')
